import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const g=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1795742187000}'),t={name:"guide/faq.md"};function r(n,e,i,l,s,p){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="和-1panel-是什么关系" tabindex="-1">和 1Panel 是什么关系？ <a class="header-anchor" href="#和-1panel-是什么关系" aria-label="Permalink to &quot;和 1Panel 是什么关系？&quot;">​</a></h2><p>目录、配置与 systemd 约定参考 1Panel：安装根 <code>/opt/mpanel</code>、<code>conf/app.yaml</code>、<code>data/</code>、<code>log/</code>、 <code>db/</code>、<code>backup/</code>、<code>mpanel-core.service</code> / <code>mpanel-agent.service</code>、<code>mpctl</code> 控制脚本。 但网站管理用 <strong>Caddy</strong> 而不是 nginx。</p><h2 id="为什么用-caddy-而不是-nginx" tabindex="-1">为什么用 Caddy 而不是 nginx？ <a class="header-anchor" href="#为什么用-caddy-而不是-nginx" aria-label="Permalink to &quot;为什么用 Caddy 而不是 nginx？&quot;">​</a></h2><p>1Panel 用 nginx + 站点配置模板；MPanel 用 Caddy 的 <code>import sites.d/*.caddy</code>。好处是自动 HTTPS、 配置可校验（<code>caddy validate</code>）、reload 原子且失败可回滚，站点模型可以完全结构化生成， 不需要维护 nginx 的 location 片段。Caddy 以 Docker 容器运行，由面板一键部署 <code>mpanel-caddy</code> 编排，不要求在宿主机安装 Caddy 二进制。</p><h2 id="三端一定要一起部署吗" tabindex="-1">三端一定要一起部署吗？ <a class="header-anchor" href="#三端一定要一起部署吗" aria-label="Permalink to &quot;三端一定要一起部署吗？&quot;">​</a></h2><p>不必。</p><ul><li>只跑 <code>mpanel-agent</code> + 任意静态服务器托管 <code>web/panel</code>：单机面板。</li><li><code>mpanel-core</code> + 多个 agent：多机面板（http / stdio / reverse-ws）。</li><li>内网机器只允许出站：用 <code>reverse-ws</code> 或边缘入网密钥。</li></ul><h2 id="core-会执行命令吗" tabindex="-1">core 会执行命令吗？ <a class="header-anchor" href="#core-会执行命令吗" aria-label="Permalink to &quot;core 会执行命令吗？&quot;">​</a></h2><p>不会。core 只做认证、机器注册、代理与聚合；所有功能在 agent 上执行。唯一的例外是 <code>MPANEL_ALLOW_STDIO=1</code> 时 core 会 spawn agent 子进程——这等价于在 core 主机执行命令，默认关闭。</p><h2 id="数据库为什么只支持-postgresql-与-redis" tabindex="-1">数据库为什么只支持 PostgreSQL 与 Redis？ <a class="header-anchor" href="#数据库为什么只支持-postgresql-与-redis" aria-label="Permalink to &quot;数据库为什么只支持 PostgreSQL 与 Redis？&quot;">​</a></h2><p>一期只适配这两种，查询界面通过 iframe 嵌入外部 dbx；agent 负责连接档案、统计、备份恢复与 一次性 handoff 票据。MySQL 等不在当前范围。</p><h2 id="前端能连多个后端吗" tabindex="-1">前端能连多个后端吗？ <a class="header-anchor" href="#前端能连多个后端吗" aria-label="Permalink to &quot;前端能连多个后端吗？&quot;">​</a></h2><p>能。连接管理中可保存多个 core / agent，切换时按连接隔离查询缓存；也支持构建期 <code>VITE_DEFAULT_BACKEND(S)</code> 与运行时 <code>config.json</code> 预置。</p><h2 id="数据存在哪里-怎么备份" tabindex="-1">数据存在哪里？怎么备份？ <a class="header-anchor" href="#数据存在哪里-怎么备份" aria-label="Permalink to &quot;数据存在哪里？怎么备份？&quot;">​</a></h2><p>core：<code>/opt/mpanel/db/*.json</code> 与 <code>conf/</code>；agent：<code>/opt/mpanel/data/</code>（状态、应用、编排、站点/文件根） 与 <code>conf/agent.yaml</code>；备份在 <code>/opt/mpanel/backup/</code>。整体备份 <code>/opt/mpanel</code> 即可；密钥文件（<code>conf/app.yaml</code> 的 <code>secret</code>、 <code>data/agent/secrets.key</code>）必须一起备份，否则已加密的 token/密码无法解密。</p><h2 id="面板端口是多少" tabindex="-1">面板端口是多少？ <a class="header-anchor" href="#面板端口是多少" aria-label="Permalink to &quot;面板端口是多少？&quot;">​</a></h2><p>默认 core <code>10086</code>、agent <code>10087</code>。1Panel 安装时随机端口；MPanel 也可以改 <code>conf/app.yaml</code> 的 <code>system.port</code> 或设置 <code>MPANEL_PORT</code>。</p><h2 id="用-gh-pages-上的面板连接自建-core-时登录不了" tabindex="-1">用 gh-pages 上的面板连接自建 core 时登录不了？ <a class="header-anchor" href="#用-gh-pages-上的面板连接自建-core-时登录不了" aria-label="Permalink to &quot;用 gh-pages 上的面板连接自建 core 时登录不了？&quot;">​</a></h2><p>浏览器把 <code>sakana-1314.github.io</code> 与你自己的域名视为<strong>跨站</strong>，会话 Cookie 是 <code>SameSite=Lax</code>， 跨站请求不会携带它，所以「登录成功但一刷新就掉线」是预期行为。两种做法：</p><ol><li><strong>用 API Token（推荐）</strong>：在面板「设置」里创建一个 write 权限 token，在连接配置里填入； 前端会用 <code>Authorization: Bearer</code> 而不是 Cookie。core 侧需要把该 origin 加进 <code>MPANEL_CORS_ORIGINS</code>（例如 <code>https://sakana-1314.github.io</code>）。</li><li><strong>同域部署</strong>：把 <code>web/panel/dist</code> 放到 core 的 <code>MPANEL_WEB_DIR</code>（默认 <code>/opt/mpanel/web</code>）， 由 core 直接托管，登录 Cookie 同站可用。</li></ol><p>自托管面板连自建 core 不受此限制。</p>',22)])])}const m=o(t,[["render",r]]);export{g as __pageData,m as default};
